package com.pricepaid;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Units;

@ConfigGroup(PricePaidConfig.GROUP)
public interface PricePaidConfig extends Config
{
	String GROUP = "pricepaid";

	@ConfigItem(
		keyName = "autoStar",
		name = "Autotrack expensive items",
		description = "Automatically track items bought above the price threshold, consumables excluded",
		position = 1
	)
	default boolean autoStar()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoStarThreshold",
		name = "Autotrack price",
		description = "Autotrack a purchase when the price per item is at least this much",
		position = 2
	)
	@Units(" gp")
	default int autoStarThreshold()
	{
		return 100_000;
	}

	@ConfigItem(
		keyName = "absoluteDates",
		name = "Exact dates",
		description = "Show purchase dates as full dates and times instead of relative time like '9 months ago'",
		position = 3
	)
	default boolean absoluteDates()
	{
		return false;
	}
}

package com.pricepaid;

import com.pricepaid.ui.PricePaidPanel;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import com.google.inject.Provides;

@Slf4j
@PluginDescriptor(
	name = "Price Paid",
	description = "Tracks what you paid for items on the GE and how their value has changed since",
	tags = {"ge", "grand", "exchange", "tracker", "tracking", "item", "paid", "cost", "purchase", "purchases", "price", "value", "gear"}
)
public class PricePaidPlugin extends Plugin
{
	// offer events within a couple ticks of login are replays of state we
	// already know about, same window the core GE plugin uses
	private static final int GE_LOGIN_BURST_WINDOW = 2;

	// GE sell tax is 2% per item rounded down, so items under 50 gp pay
	// nothing. Everything on the exemption list is cheap enough that the
	// rounding already covers it, except bonds
	private static final long GE_TAX_CAP_PER_ITEM = 5_000_000L;
	private static final int OLD_SCHOOL_BOND_ITEM_ID = 13190;

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private PurchaseDataManager dataManager;

	@Inject
	private PricePaidConfig config;

	@Inject
	private PricePaidPanel panel;

	private NavigationButton navButton;
	private int lastLoginTick = -1;

	@Provides
	PricePaidConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PricePaidConfig.class);
	}

	@Override
	protected void startUp()
	{
		// coin stack sprite, scaled down to fit the toolbar
		BufferedImage icon = ImageUtil.resizeImage(
			ImageUtil.loadImageResource(PricePaidPlugin.class, "icon.png"), 16, 11);
		navButton = NavigationButton.builder()
			.tooltip("Price Paid")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			dataManager.load();
			panel.refresh();
		}
	}

	@Override
	protected void shutDown()
	{
		panel.commitPendingUnstars();
		clientToolbar.removeNavigation(navButton);
		navButton = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			lastLoginTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// switched character, or profile data just became available at login
		dataManager.load();
		panel.refresh();
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		final int slot = event.getSlot();
		final GrandExchangeOffer offer = event.getOffer();
		final GrandExchangeOfferState state = offer.getState();

		if (state == GrandExchangeOfferState.EMPTY && client.getGameState() != GameState.LOGGED_IN)
		{
			// login fires EMPTY for every slot before the real offers come
			// in, acting on it would wipe the snapshots we diff against
			return;
		}

		if (state == GrandExchangeOfferState.EMPTY)
		{
			// offer collected, the slot is actually free now
			dataManager.clearSlot(slot);
			return;
		}

		if (state == GrandExchangeOfferState.SELLING
			|| state == GrandExchangeOfferState.SOLD
			|| state == GrandExchangeOfferState.CANCELLED_SELL)
		{
			// sells of tracked items get recorded so a finished position can
			// show its outcome. Other sells still snapshot the slot so a sell
			// replacing a buy is never misread as a continuation of it
			final SavedOffer savedSell = dataManager.loadSlot(slot);
			final int soldDelta;
			final long receivedDelta;
			if (savedSell != null && savedSell.isSameOffer(offer))
			{
				soldDelta = offer.getQuantitySold() - savedSell.getQuantitySold();
				receivedDelta = (long) offer.getSpent() - savedSell.getSpent();
			}
			else
			{
				soldDelta = offer.getQuantitySold();
				receivedDelta = offer.getSpent();
			}
			dataManager.saveSlot(slot, SavedOffer.from(offer));

			if (soldDelta > 0 && receivedDelta > 0 && dataManager.isTracked(offer.getItemId()))
			{
				// the offer reports the gross sale value but the GE keeps its
				// tax, record what actually reaches the coffer
				long tax = geTax(offer.getItemId(), receivedDelta / soldDelta) * soldDelta;
				dataManager.recordSale(offer.getItemId(), soldDelta, receivedDelta - tax);
				panel.refresh();
			}
			return;
		}

		// down here we have a buy, a cancelled buy still keeps whatever
		// partially filled
		final SavedOffer saved = dataManager.loadSlot(slot);

		final int quantityDelta;
		final long spentDelta;
		if (saved != null && saved.isSameOffer(offer))
		{
			quantityDelta = offer.getQuantitySold() - saved.getQuantitySold();
			spentDelta = (long) offer.getSpent() - saved.getSpent();
		}
		else
		{
			quantityDelta = offer.getQuantitySold();
			spentDelta = offer.getSpent();
		}

		dataManager.saveSlot(slot, SavedOffer.from(offer));

		if (quantityDelta <= 0 || spentDelta <= 0)
		{
			return;
		}

		// inside the login burst this is a fill that happened while logged
		// out, so the timestamp we record is really just when we noticed
		final boolean approximate = lastLoginTick >= 0
			&& client.getTickCount() <= lastLoginTick + GE_LOGIN_BURST_WINDOW;

		final ItemComposition composition = itemManager.getItemComposition(offer.getItemId());
		final String itemName = composition.getName();

		PurchaseRecord record = dataManager.recordPurchase(
			offer.getItemId(), itemName, quantityDelta, spentDelta, approximate);
		if (record == null)
		{
			return;
		}

		log.debug("Recorded purchase: {} x{} for {} gp (approximate={})",
			itemName, quantityDelta, spentDelta, approximate);

		if (config.autoStar()
			&& !dataManager.isTracked(offer.getItemId())
			&& record.unitPrice() >= config.autoStarThreshold()
			&& !isConsumable(composition))
		{
			dataManager.star(offer.getItemId(), itemName);
			log.debug("Autotracked {}", itemName);
		}

		panel.refresh();
	}

	/** Sell tax per item, 2% rounded down with the cap. Bonds are exempt. */
	private static long geTax(int itemId, long unitPrice)
	{
		if (itemId == OLD_SCHOOL_BOND_ITEM_ID)
		{
			return 0;
		}
		return Math.min(unitPrice * 2 / 100, GE_TAX_CAP_PER_ITEM);
	}

	/**
	 * Food and potions never get autotracked no matter the price. Checking
	 * the item's own menu actions covers both without any name lists.
	 */
	private static boolean isConsumable(ItemComposition composition)
	{
		String[] actions = composition.getInventoryActions();
		if (actions == null)
		{
			return false;
		}
		for (String action : actions)
		{
			if ("Eat".equalsIgnoreCase(action) || "Drink".equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}

}

package com.pricepaid;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Owns the purchase data for the current character and persists it in profile
 * scoped config, which syncs between PCs through the runelite.net account.
 *
 * The "recent" key holds a rolling buffer of the last {@link #RECENT_CAP}
 * buys, "tracked" holds starred items which are kept until unstarred, and the
 * "geslot" keys hold offer snapshots used to diff replayed login events.
 */
@Slf4j
@Singleton
public class PurchaseDataManager
{
	// how many purchases the recent feed keeps before rolling over
	static final int RECENT_CAP = 200;
	// nobody sane hits this, purely a guard against a duplication bug
	static final int TRACKED_CAP = 500;
	// per tracked item, older records collapse into carried totals past this
	static final int PURCHASES_PER_ITEM_CAP = 100;

	private static final String KEY_RECENT = "recent";
	private static final String KEY_TRACKED = "tracked";
	private static final String KEY_SLOT_PREFIX = "geslot_";

	private static final Type RECENT_TYPE = new TypeToken<List<PurchaseRecord>>()
	{
	}.getType();
	private static final Type TRACKED_TYPE = new TypeToken<List<TrackedItem>>()
	{
	}.getType();

	private final ConfigManager configManager;
	private final Gson gson;

	private final Map<Integer, TrackedItem> tracked = new LinkedHashMap<>();
	// newest first
	private final List<PurchaseRecord> recent = new ArrayList<>();

	@Inject
	private PurchaseDataManager(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public synchronized void load()
	{
		recent.clear();
		tracked.clear();

		String recentJson = configManager.getRSProfileConfiguration(PricePaidConfig.GROUP, KEY_RECENT);
		if (recentJson != null)
		{
			try
			{
				List<PurchaseRecord> loaded = gson.fromJson(recentJson, RECENT_TYPE);
				if (loaded != null)
				{
					recent.addAll(loaded);
				}
			}
			catch (JsonSyntaxException e)
			{
				log.warn("Corrupt recent purchase data, discarding", e);
			}
		}

		String trackedJson = configManager.getRSProfileConfiguration(PricePaidConfig.GROUP, KEY_TRACKED);
		if (trackedJson != null)
		{
			try
			{
				List<TrackedItem> loaded = gson.fromJson(trackedJson, TRACKED_TYPE);
				if (loaded != null)
				{
					for (TrackedItem item : loaded)
					{
						tracked.put(item.getItemId(), item);
					}
				}
			}
			catch (JsonSyntaxException e)
			{
				log.warn("Corrupt tracked item data, discarding", e);
			}
		}
	}

	public synchronized SavedOffer loadSlot(int slot)
	{
		String json = configManager.getRSProfileConfiguration(PricePaidConfig.GROUP, KEY_SLOT_PREFIX + slot);
		if (json == null)
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, SavedOffer.class);
		}
		catch (JsonSyntaxException e)
		{
			return null;
		}
	}

	public synchronized void saveSlot(int slot, SavedOffer offer)
	{
		configManager.setRSProfileConfiguration(PricePaidConfig.GROUP, KEY_SLOT_PREFIX + slot, gson.toJson(offer));
	}

	public synchronized void clearSlot(int slot)
	{
		configManager.unsetRSProfileConfiguration(PricePaidConfig.GROUP, KEY_SLOT_PREFIX + slot);
	}

	/**
	 * Records a buy fill. Returns the record, or null if it was rejected by the
	 * duplicate guard.
	 */
	public synchronized PurchaseRecord recordPurchase(int itemId, String itemName, int quantity, long spent, boolean approximate)
	{
		long now = System.currentTimeMillis();

		// an identical fill of the same item in the same millisecond can only
		// be the same event firing twice
		for (PurchaseRecord existing : recent)
		{
			if (existing.getItemId() == itemId
				&& existing.getQuantity() == quantity
				&& existing.getSpent() == spent
				&& existing.getTime() == now)
			{
				return null;
			}
		}

		PurchaseRecord record = new PurchaseRecord(itemId, itemName, quantity, spent, now, approximate);

		recent.add(0, record);
		while (recent.size() > RECENT_CAP)
		{
			recent.remove(recent.size() - 1);
		}

		TrackedItem entry = tracked.get(itemId);
		if (entry != null)
		{
			appendToTracked(entry, record);
		}

		save();
		return record;
	}

	public synchronized boolean isTracked(int itemId)
	{
		return tracked.containsKey(itemId);
	}

	/**
	 * Stars an item, seeding the tracked entry with every purchase of it
	 * still in the recent buffer. Does nothing if already tracked.
	 */
	public synchronized void star(int itemId, String itemName)
	{
		if (tracked.containsKey(itemId) || tracked.size() >= TRACKED_CAP)
		{
			return;
		}

		TrackedItem entry = new TrackedItem(itemId, itemName);
		List<PurchaseRecord> matching = new ArrayList<>();
		for (PurchaseRecord record : recent)
		{
			if (record.getItemId() == itemId)
			{
				matching.add(record);
			}
		}
		// recent is newest first but tracked purchases are stored oldest first
		for (int i = matching.size() - 1; i >= 0; i--)
		{
			appendToTracked(entry, matching.get(i));
		}
		tracked.put(itemId, entry);
		save();
	}

	/**
	 * Records a GE sell fill of a tracked item. Does nothing for untracked
	 * items. netReceived is the coins actually collected after GE tax.
	 */
	public synchronized void recordSale(int itemId, int quantity, long netReceived)
	{
		TrackedItem entry = tracked.get(itemId);
		if (entry == null)
		{
			return;
		}
		entry.setSoldQuantity(entry.getSoldQuantity() + quantity);
		entry.setSoldReceived(entry.getSoldReceived() + netReceived);
		entry.setLastSaleTime(System.currentTimeMillis());
		save();
	}

	/** Unstars an item, discarding its tracked purchase history. */
	public synchronized void unstar(int itemId)
	{
		if (tracked.remove(itemId) != null)
		{
			save();
		}
	}

	public synchronized List<PurchaseRecord> getRecent()
	{
		return new ArrayList<>(recent);
	}

	/** Tracked items, most recently purchased first. */
	public synchronized List<TrackedItem> getTracked()
	{
		List<TrackedItem> items = new ArrayList<>(tracked.values());
		items.sort(Comparator.comparingLong(TrackedItem::lastPurchaseTime).reversed());
		return items;
	}

	private void appendToTracked(TrackedItem entry, PurchaseRecord record)
	{
		entry.getPurchases().add(record);
		while (entry.getPurchases().size() > PURCHASES_PER_ITEM_CAP)
		{
			PurchaseRecord oldest = entry.getPurchases().remove(0);
			entry.setCarriedQuantity(entry.getCarriedQuantity() + oldest.getQuantity());
			entry.setCarriedSpent(entry.getCarriedSpent() + oldest.getSpent());
		}
	}

	private void save()
	{
		configManager.setRSProfileConfiguration(PricePaidConfig.GROUP, KEY_RECENT, gson.toJson(recent, RECENT_TYPE));
		configManager.setRSProfileConfiguration(PricePaidConfig.GROUP, KEY_TRACKED,
			gson.toJson(new ArrayList<>(tracked.values()), TRACKED_TYPE));
	}
}

package com.pricepaid;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A single GE buy, one fill delta of one offer.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class PurchaseRecord
{
	private int itemId;
	private String itemName;
	private int quantity;
	private long spent;
	private long time;
	// true when the fill was only noticed at login, meaning it happened at
	// some unknown point while logged out and time is just the detection time
	private boolean approximate;

	public long unitPrice()
	{
		return quantity > 0 ? spent / quantity : 0;
	}
}

package com.pricepaid;

/**
 * Formats a timestamp relative to now, e.g. "9 months ago".
 */
public final class RelativeTime
{
	private RelativeTime()
	{
	}

	public static String format(long time)
	{
		long seconds = Math.max(0, (System.currentTimeMillis() - time) / 1000);

		if (seconds < 60)
		{
			return "just now";
		}

		long minutes = seconds / 60;
		if (minutes < 60)
		{
			return plural(minutes, "minute");
		}

		long hours = minutes / 60;
		if (hours < 24)
		{
			return plural(hours, "hour");
		}

		long days = hours / 24;
		if (days == 1)
		{
			return "yesterday";
		}
		if (days < 14)
		{
			return plural(days, "day");
		}

		long weeks = days / 7;
		if (days < 60)
		{
			return plural(weeks, "week");
		}

		long months = days / 30;
		if (months < 12)
		{
			return plural(months, "month");
		}

		long years = days / 365;
		return plural(Math.max(1, years), "year");
	}

	private static String plural(long n, String unit)
	{
		return n + " " + unit + (n == 1 ? "" : "s") + " ago";
	}
}

package com.pricepaid;

import lombok.Data;
import lombok.NoArgsConstructor;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Snapshot of a GE slot's offer, saved per character so that offer events
 * replayed at login can be diffed against the last state we saw instead of
 * being counted twice. Fills that completed while logged out fall out of the
 * same diff.
 */
@Data
@NoArgsConstructor
public class SavedOffer
{
	private int itemId;
	private int quantitySold;
	private int totalQuantity;
	private long price;
	private long spent;
	private GrandExchangeOfferState state;

	public static SavedOffer from(GrandExchangeOffer offer)
	{
		SavedOffer saved = new SavedOffer();
		saved.itemId = offer.getItemId();
		saved.quantitySold = offer.getQuantitySold();
		saved.totalQuantity = offer.getTotalQuantity();
		saved.price = offer.getPrice();
		saved.spent = offer.getSpent();
		saved.state = offer.getState();
		return saved;
	}

	/**
	 * Whether the given offer is a later state of the offer this snapshot was
	 * taken from, rather than a new offer in the same slot.
	 */
	public boolean isSameOffer(GrandExchangeOffer offer)
	{
		return itemId == offer.getItemId()
			&& price == offer.getPrice()
			&& totalQuantity == offer.getTotalQuantity()
			&& quantitySold <= offer.getQuantitySold()
			&& spent <= offer.getSpent();
	}
}

package com.pricepaid;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A starred item. All of its purchases are kept until the item is unstarred.
 * Past the purchase cap the oldest records get collapsed into the carried
 * totals so the average cost stays correct.
 */
@Data
@NoArgsConstructor
public class TrackedItem
{
	private int itemId;
	private String itemName;
	private List<PurchaseRecord> purchases = new ArrayList<>();
	private long carriedQuantity;
	private long carriedSpent;
	// sells of this item while tracked, so a finished position can show what
	// it bought and sold for. soldReceived is net of GE tax
	private long soldQuantity;
	private long soldReceived;
	private long lastSaleTime;

	public TrackedItem(int itemId, String itemName)
	{
		this.itemId = itemId;
		this.itemName = itemName;
	}

	public long totalQuantity()
	{
		long qty = carriedQuantity;
		for (PurchaseRecord p : purchases)
		{
			qty += p.getQuantity();
		}
		return qty;
	}

	public long totalSpent()
	{
		long spent = carriedSpent;
		for (PurchaseRecord p : purchases)
		{
			spent += p.getSpent();
		}
		return spent;
	}

	public long averageUnitPrice()
	{
		long qty = totalQuantity();
		return qty > 0 ? totalSpent() / qty : 0;
	}

	public long lastPurchaseTime()
	{
		long last = 0;
		for (PurchaseRecord p : purchases)
		{
			last = Math.max(last, p.getTime());
		}
		return last;
	}

	/** Whether the whole position has been sold back to the GE. */
	public boolean fullySold()
	{
		long qty = totalQuantity();
		return qty > 0 && soldQuantity >= qty;
	}
}

